-- Hungary deep-dive ES/DE/FR translations (completing 350).
-- INSERT OR IGNORE throughout.

-- ==================== es ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Reporte de datos de transacciones en tiempo real (RTIR) desde 2018, con un mandato de facturación electrónica B2B limitado al sector energético/agua desde 2025 -- todavía no existe un mandato general de facturación electrónica B2B, aunque hay uno en fase de consulta', 'Esta página de análisis refleja la orientación pública de NAV y la información del sector disponible a principios de agosto de 2026, y se ofrece a título informativo general, no como asesoramiento legal o fiscal. El futuro marco integral de facturación electrónica de Hungría seguía en fase de consulta pública en el momento de redactar esto, sin fecha promulgada -- confirme el estado actual directamente con NAV o con un asesor fiscal húngaro antes de basar en esta página sus decisiones de cumplimiento.', 'El sistema de Reporte de Facturas en Tiempo Real (RTIR) de Hungría es uno de los regímenes de reporte de transacciones más maduros de Europa: lanzado el 1 de julio de 2018 para facturas B2B nacionales por encima de un umbral de IVA de 100.000 HUF, el umbral se eliminó el 1 de julio de 2020, y el alcance volvió a ampliarse el 1 de enero de 2021 para cubrir facturas B2C, de exportación e intracomunitarias -- llegados a ese punto, RTIR abarcaba prácticamente toda factura relevante a efectos de IVA que emite una empresa húngara. Fundamentalmente, RTIR reporta los DATOS de la factura al sistema Online Szamla de NAV; nunca ha exigido que la factura en sí se emita electrónicamente. Eso cambió, de forma limitada, a partir del 1 de julio de 2025: los proveedores de electricidad, gas natural y agua deben ahora emitir facturas electrónicas reales para los suministros B2B a clientes no particulares -- el primer mandato genuino de emisión de facturación electrónica de Hungría, aunque específico de un sector. A partir del 1 de septiembre de 2026, la red de reporte se amplía de nuevo, esta vez a los recibos. Por separado, NAV y el Ministerio de Economía Nacional abrieron una consulta pública en noviembre de 2025, actualizada como documento de concepto el 31 de marzo de 2026, sobre un futuro marco integral de facturación electrónica que cubriría las transacciones B2B y B2G nacionales e intracomunitarias -- propuesto, pero aún no promulgado. Decida lo que decida Hungría a nivel nacional, el suelo transfronterizo de ViDA de la UE se aplica de todos modos a partir del 1 de julio de 2030.', 'RTIR transmite los datos de la factura a través de la API de Online Szamla de NAV, normalmente en el esquema XML propio de NAV generado directamente por el software de facturación/contabilidad; no exige un formato de documento de factura específico, ya que la factura en sí puede seguir siendo en papel o PDF fuera del sector energético/agua. Donde sí se aplica un mandato real de facturación electrónica (suministros B2B de electricidad, gas y agua desde julio de 2025), la legislación tampoco prescribe un formato específico -- cualquier formato y método de transmisión aceptado por NAV es válido. La facturación B2G sigue el Estándar Europeo EN 16931, como en todo Estado miembro de la UE.', 'La obligación de reporte de datos de RTIR cubre ahora prácticamente a todas las empresas registradas a efectos de IVA en Hungría, tanto para facturas B2B nacionales como B2C, de exportación e intracomunitarias -- un alcance que tardó tres pasos (2018, 2020, 2021) en alcanzarse. Superpuesto a esto, el mandato de emisión de facturación electrónica de julio de 2025 es deliberadamente limitado: solo proveedores de electricidad, gas natural y agua, solo para suministros B2B a clientes no particulares. A partir de septiembre de 2026, todas las empresas -- no solo las registradas a efectos de IVA que realizan suministros B2B -- entran en el ámbito del reporte de datos de recibos. Todavía no existe un mandato general de facturación electrónica B2B a nivel nacional; el alcance propuesto por la consulta de noviembre de 2025 (B2B nacional, B2B intracomunitario y B2G) no tiene fecha confirmada.', 'Dado que la obligación de reporte de RTIR ya es prácticamente universal, el trabajo a corto plazo de la mayoría de las empresas húngaras consiste en añadir nuevas obligaciones sobre la conectividad RTIR ya existente, más que en construir el cumplimiento desde cero: los proveedores de energía/agua necesitan capacidad real de facturación electrónica, la mayoría de las demás empresas deben prepararse para el reporte de datos de recibos antes de septiembre de 2026, y todas deben seguir de cerca la consulta integral de facturación electrónica por si surge un futuro mandato nacional B2B.', 'Hungría respalda RTIR con sanciones reales y documentadas: hasta 500.000 HUF por factura no reportada, reportada con retraso, de forma incompleta, incorrecta o falsa, más una multa aparte de 300.000 HUF (desde el 1 de enero de 2025) por no responder a una solicitud de aclaración de NAV en un plazo de 15 días. No se encontró en la investigación, a fecha de esta redacción, un régimen de sanciones específico para el mandato más limitado de facturación electrónica de energía/agua de julio de 2025.', 'La Administración Nacional de Hacienda y Aduanas de Hungría (NAV) opera el Reporte de Facturas en Tiempo Real (RTIR) desde el 1 de julio de 2018, que ahora cubre prácticamente toda factura relevante a efectos de IVA que emite una empresa húngara -- pero RTIR es una obligación de reporte de DATOS de la transacción, no un mandato de formato de facturación electrónica; la factura subyacente puede seguir siendo en papel o PDF. Eso cambió de forma limitada a partir del 1 de julio de 2025, cuando los proveedores de electricidad, gas natural y agua pasaron a estar obligados a emitir realmente facturas electrónicas para los suministros B2B a clientes no particulares -- el primer mandato real de emisión de facturación electrónica de Hungría, aunque específico de un sector en lugar de para toda la economía. A partir del 1 de septiembre de 2026, el reporte obligatorio se amplía de nuevo, esta vez a los datos de recibos. Un futuro marco integral de facturación electrónica -- que cubriría las transacciones B2B y B2G nacionales e intracomunitarias -- se abrió a consulta pública en noviembre de 2025 y se actualizó como documento de concepto el 31 de marzo de 2026, pero sigue siendo una propuesta, no una norma promulgada. Con independencia del calendario nacional propio de Hungría, la directiva del IVA en la Era Digital (ViDA) de la UE fija un suelo transfronterizo B2B confirmado a partir del 1 de julio de 2030.', '🇭🇺' FROM countries WHERE name_en = 'Hungary';

