INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '1 jul 2025', 'Comienza el primer mandato real de facturación electrónica (energía/agua B2B)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Hungary' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '1 sep 2026', 'El reporte de datos de recibos a NAV pasa a ser obligatorio' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Hungary' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '2030', 'Suelo transfronterizo de la UE (ViDA, confirmado)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Hungary' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Formato y estándar', '[["Formato de datos RTIR", "Esquema XML propio de NAV, enviado a través de la API de Online Szamla -- no se exige un formato específico para el documento de factura subyacente"], ["Facturas electrónicas de energía/agua (desde jul. 2025)", "No se prescribe un formato específico -- cualquier formato y método de transmisión aceptado por NAV es válido"], ["B2G", "EN 16931, el Estándar Europeo de facturación electrónica, como en todo Estado miembro de la UE"], ["Base legal", "Ley del IVA (Ley CXXVII de 2007) y sus decretos de desarrollo de RTIR; el mandato de energía/agua se encuentra en legislación sectorial aparte"]]', 'No confunda el envío obligatorio de datos XML de RTIR con un requisito de emitir la factura en sí en ese formato -- fuera del sector energía/agua, una empresa húngara puede seguir enviando una factura en papel o PDF y cumplir plenamente con RTIR.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Identificadores y registro', '[["Registro del contribuyente", "Número de IVA/fiscal húngaro, registrado ante NAV"], ["Conexión técnica RTIR", "Portal Online Szamla (onlineszamla.nav.gov.hu) -- integración directa por API o carga manual web"], ["Organismo responsable", "Nemzeti Ado- es Vamhivatal (NAV) -- Administración Nacional de Hacienda y Aduanas"], ["Empresas extranjeras registradas a efectos de IVA", "Incluidas en RTIR en las mismas condiciones que los contribuyentes nacionales una vez registradas a efectos de IVA en Hungría"]]', 'La mayoría del software de facturación/contabilidad usado en Hungría ya incorpora el reporte RTIR -- confirme que el suyo envía realmente de forma automática, en lugar de depender de la carga manual, dado lo ajustado del plazo para facturas de software.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Contenido obligatorio', '[["Campos de datos RTIR", "Números fiscales de emisor/comprador, número de factura, fechas, desglose detallado del IVA, importes neto y bruto"], ["Facturas de software", "Se reportan de inmediato, sin intervención humana"], ["Facturas manuales/en papel", "5 días naturales (IVA de 100.000-500.000 HUF) o 1 día natural (IVA superior a 500.000 HUF) -- los umbrales originales de 2018 siguen marcando los plazos de las facturas manuales aunque el umbral del alcance del reporte en sí se eliminara en 2020"], ["Conservación", "8 años para facturas y respuestas de envío de RTIR"]]', 'Los niveles de plazo para facturas manuales son un legado del diseño original del umbral de 2018 -- conviene conocerlos aunque ahora toda factura, sin importar su valor, deba reportarse.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'El flujo de emisión y luego reporte', 'Fuera del sector energía/agua, una factura húngara recorre esta secuencia -- observe que RTIR reporta los DATOS de la factura, no el documento en sí:', 'La factura es legalmente válida al emitirse, sea cual sea su formato -- no se pide a NAV que la despache o apruebe primero, a diferencia de los mandatos de modelo de aclaración cubiertos en otras partes de este seguimiento (Colombia, Argentina, Jordania). Solo para los suministros B2B de energía/agua (desde julio de 2025) el documento de factura en sí debe ser realmente electrónico.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Hungary';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'Factura emitida al comprador -- en papel, PDF o electrónica, todas válidas legalmente fuera del B2B de energía/agua' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Hungary' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'Datos de la factura reportados a NAV vía Online Szamla -- de inmediato para facturas de software' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Hungary' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'NAV cruza los datos de factura reportados con las declaraciones de IVA presentadas' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Hungary' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'Desde sep. 2026: los datos de recibo subyacentes se reportan por separado, con el mismo principio de tiempo real' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Hungary' AND st.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Qué es realmente obligatorio hoy, por capas', '[["Reporte de datos RTIR", "Prácticamente todas las empresas registradas a efectos de IVA -- B2B nacional, B2C, exportación, intracomunitario (desde 2021)"], ["Emisión de facturas electrónicas", "Solo proveedores de electricidad, gas natural y agua, suministros B2B a clientes no particulares (desde jul. 2025)"], ["Reporte de datos de recibos", "Todas las empresas, desde el 1 de septiembre de 2026"], ["Facturación electrónica B2B nacional general", "No es obligatoria -- propuesta en una consulta de noviembre de 2025, sin fecha promulgada"]]', 'Conviene precisar qué capa le aplica: casi toda empresa húngara ya reporta bajo RTIR, pero muy pocas están todavía obligadas a emitir realmente una factura electrónica.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'El marco integral propuesto (aún no es ley)', '[["Estado", "Consulta pública abierta en nov. 2025, documento de concepto actualizado publicado el 31 mar. 2026"], ["Alcance propuesto", "B2B nacional, B2B intracomunitario y B2G"], ["Formato propuesto", "XML unificado conforme con EN 16931"], ["Reporte por parte del comprador propuesto", "Los compradores nacionales reportarían las facturas recibidas en un plazo de 5 días"]]', 'Trate cada detalle aquí como una propuesta, no como un compromiso -- la propia consulta de NAV deja claro que la forma final y la fecha siguen abiertas.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '💰 HUF 500.000 por cada fallo de reporte RTIR', NULL, NULL, 'Las empresas se enfrentan a multas de hasta 500.000 HUF por factura no reportada, reportada con retraso, de forma incompleta, incorrecta o falsa a través de RTIR. Dado que el alcance de RTIR es ahora prácticamente universal, esta es la exposición a sanciones que afecta a casi toda empresa húngara registrada a efectos de IVA, no un caso límite excepcional.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '📋 HUF 300.000 por ignorar una solicitud de aclaración de NAV', NULL, NULL, 'Desde el 1 de enero de 2025, no responder a una solicitud de aclaración de NAV sobre una factura reportada en un plazo de 15 días conlleva una multa aparte de 300.000 HUF -- una sanción procedimental más reciente que se suma a la multa principal de reporte RTIR anterior.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '🗓 Un régimen construido por capas, no una única fecha de mandato', NULL, NULL, 'La historia de Hungría avanzó en pasos diferenciados, cada uno cambiando algo distinto: el lanzamiento de RTIR (2018) y sus dos ampliaciones de alcance (2020, 2021) construyeron una obligación de reporte de datos prácticamente universal; la norma de energía/agua de 2025 añadió un mandato de emisión de facturación electrónica limitado pero real; 2026 extiende el reporte a los recibos; y un marco integral B2B/B2G sigue siendo una propuesta viva más que una fecha fija. Identifique qué capa cambia realmente cada plazo antes de asumir que le aplica a su empresa.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Factura no reportada, reportada con retraso, de forma incompleta, incorrecta o falsa vía RTIR', 'Hasta HUF 500.000 por factura', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Hungary' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'No responder a una solicitud de aclaración de NAV en un plazo de 15 días (desde el 1 ene. 2025)', 'HUF 300.000', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Hungary' AND pr.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme que su reporte RTIR está totalmente automatizado y cubre todo tipo de factura', 'RTIR cubre ahora facturas B2B nacionales, B2C, de exportación e intracomunitarias sin umbral de valor -- confirme que su software de facturación/contabilidad las reporta todas de inmediato, no solo un subconjunto.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Hungary' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Si suministra electricidad, gas o agua a empresas húngaras, pase a una facturación electrónica real', 'Desde el 1 de julio de 2025, los suministros B2B en este sector exigen una factura electrónica real, no solo datos reportados vía RTIR -- confirme que su proceso de facturación ha hecho ese cambio.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Hungary' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Prepárese para el reporte de datos de recibos antes del 1 de septiembre de 2026', 'Confirme si su sistema de punto de venta ya usa una caja registradora conectada o electrónica -- si no, planifique ya el reporte manual de recibos en 3 días y la transición completa a cajas electrónicas antes del 1 de julio de 2028.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Hungary' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Siga de cerca la consulta integral de facturación electrónica de NAV por si surge un futuro mandato B2B nacional', 'La consulta de noviembre de 2025 y el documento de concepto de marzo de 2026 proponen una facturación XML unificada conforme con EN 16931 y reporte por parte del comprador -- todavía sin fecha promulgada, pero vale la pena seguirlo dado el alcance que ya tiene la infraestructura de reporte de RTIR.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Hungary' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Prepárese en cualquier caso para el suelo transfronterizo confirmado de la UE de 2030', 'Toda empresa que comercie de forma transfronteriza dentro de la UE necesita capacidad de facturación electrónica y reporte digital conforme con EN 16931 a partir del 1 de julio de 2030 -- esta fecha la fija la directiva de la UE, no la discreción húngara.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Hungary' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'NAV — Online Szamla (reporte de facturas en tiempo real)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Hungary' AND pt.sort_order = 0;
