-- ==================== de ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Echtzeit-Transaktionsdatenmeldung (RTIR) seit 2018, ergänzt um eine auf den Energie-/Wassersektor beschränkte B2B-E-Rechnungspflicht seit 2025 -- noch keine allgemeine B2B-E-Rechnungspflicht, aber eine befindet sich in der Konsultation', 'Diese Analyseseite spiegelt öffentlich verfügbare Hinweise der NAV und Brancheninformationen mit Stand Anfang August 2026 wider und dient allgemeinen Informationszwecken, nicht als Rechts- oder Steuerberatung. Ungarns umfassendes künftiges E-Rechnungs-Rahmenwerk befand sich zum Zeitpunkt der Erstellung noch in der öffentlichen Konsultationsphase, ohne verabschiedetes Datum -- bestätigen Sie den aktuellen Stand direkt bei der NAV oder einem ungarischen Steuerberater, bevor Sie sich bei Compliance-Entscheidungen auf diese Seite verlassen.', 'Ungarns System zur Echtzeit-Rechnungsmeldung (RTIR) ist eines der ausgereiftesten Transaktionsmeldesysteme Europas: eingeführt am 1. Juli 2018 für inländische B2B-Rechnungen oberhalb einer USt-Schwelle von 100.000 HUF, wurde die Schwelle am 1. Juli 2020 abgeschafft, und der Anwendungsbereich wurde am 1. Januar 2021 erneut auf B2C-, Export- und innergemeinschaftliche Rechnungen ausgeweitet -- damit erfasste RTIR im Wesentlichen jede umsatzsteuerlich relevante Rechnung, die ein ungarisches Unternehmen ausstellt. Entscheidend: RTIR meldet Rechnungsdaten an das Online-Szamla-System der NAV; es hat nie verlangt, dass die Rechnung selbst elektronisch ausgestellt wird. Das änderte sich, begrenzt, ab dem 1. Juli 2025: Strom-, Erdgas- und Wasserversorger müssen nun tatsächliche E-Rechnungen für B2B-Lieferungen an nicht-private Kunden ausstellen -- Ungarns erste echte E-Rechnungspflicht, wenn auch sektorspezifisch. Ab dem 1. September 2026 weitet sich das Meldenetz erneut aus, diesmal auf Belege. Separat eröffneten die NAV und das Ministerium für Nationale Wirtschaft im November 2025 eine öffentliche Konsultation, aktualisiert als Konzeptpapier am 31. März 2026, zu einem umfassenden künftigen E-Rechnungs-Rahmenwerk für inländische und innergemeinschaftliche B2B- sowie B2G-Transaktionen -- vorgeschlagen, aber noch nicht verabschiedet. Was auch immer Ungarn innerstaatlich entscheidet, die grenzüberschreitende ViDA-Untergrenze der EU gilt ohnehin ab dem 1. Juli 2030.', 'RTIR übermittelt Rechnungsdaten über die Online-Szamla-API der NAV, in der Regel im eigenen XML-Schema der NAV, das direkt von Rechnungs-/Buchhaltungssoftware erzeugt wird; ein bestimmtes Rechnungsdokumentformat wird nicht vorgeschrieben, da die Rechnung selbst außerhalb des Energie-/Wassersektors weiterhin auf Papier oder als PDF vorliegen kann. Wo tatsächlich eine echte E-Rechnungspflicht gilt (B2B-Lieferungen von Strom, Gas und Wasser seit Juli 2025), schreibt die Gesetzgebung ebenfalls kein bestimmtes Format vor -- jedes von der NAV akzeptierte Format und jeder akzeptierte Übermittlungsweg ist zulässig. Die B2G-Rechnungsstellung folgt dem europäischen Standard EN 16931, wie in jedem EU-Mitgliedstaat.', 'Die Datenmeldepflicht von RTIR erfasst inzwischen praktisch alle umsatzsteuerlich registrierten Unternehmen in Ungarn, gleichermaßen für inländische B2B-, B2C-, Export- und innergemeinschaftliche Rechnungen -- ein Umfang, der drei Schritte (2018, 2020, 2021) brauchte, um erreicht zu werden. Darüber hinaus ist die E-Rechnungspflicht vom Juli 2025 bewusst eng gefasst: nur Strom-, Erdgas- und Wasserversorger, nur für B2B-Lieferungen an nicht-private Kunden. Ab September 2026 fallen alle Unternehmen -- nicht nur umsatzsteuerlich registrierte mit B2B-Lieferungen -- unter die Belegdatenmeldepflicht. Eine allgemeine inländische B2B-E-Rechnungspflicht existiert noch nicht; der vorgeschlagene Umfang der Konsultation vom November 2025 (inländisches B2B, innergemeinschaftliches B2B und B2G) hat kein bestätigtes Datum.', 'Da die Meldepflicht von RTIR bereits nahezu universell ist, besteht die kurzfristige Aufgabe der meisten ungarischen Unternehmen eher darin, neue Pflichten auf die bestehende RTIR-Anbindung aufzusetzen, als Compliance von Grund auf neu aufzubauen: Energie-/Wasserversorger benötigen echte E-Rechnungsfähigkeit, die meisten anderen Unternehmen müssen sich bis September 2026 auf die Belegdatenmeldung vorbereiten, und alle sollten die umfassende E-Rechnungs-Konsultation im Hinblick auf eine künftige inländische B2B-Pflicht im Blick behalten.', 'Ungarn untermauert RTIR mit realen, belegten Sanktionen: bis zu 500.000 HUF je nicht gemeldeter, verspätet, unvollständig, unrichtig oder wahrheitswidrig gemeldeter Rechnung, zuzüglich eines gesonderten Bußgelds von 300.000 HUF (seit 1. Januar 2025) für die Nichtbeantwortung einer NAV-Klärungsanfrage innerhalb von 15 Tagen. Für die engere E-Rechnungspflicht im Energie-/Wassersektor ab Juli 2025 wurde bei der Recherche zum Zeitpunkt der Erstellung kein eigenes Sanktionsschema gefunden.', 'Ungarns Nationale Steuer- und Zollverwaltung (NAV) betreibt seit dem 1. Juli 2018 die Echtzeit-Rechnungsmeldung (RTIR), die inzwischen praktisch jede umsatzsteuerlich relevante Rechnung erfasst, die ein ungarisches Unternehmen ausstellt -- RTIR ist jedoch eine Pflicht zur Meldung von Transaktions-DATEN, keine E-Rechnungs-Formatpflicht; die zugrunde liegende Rechnung kann weiterhin auf Papier oder als PDF vorliegen. Das änderte sich begrenzt ab dem 1. Juli 2025, als Strom-, Erdgas- und Wasserversorger verpflichtet wurden, für B2B-Lieferungen an nicht-private Kunden tatsächlich elektronische Rechnungen auszustellen -- Ungarns erste echte E-Rechnungspflicht, wenn auch sektorspezifisch statt gesamtwirtschaftlich. Ab dem 1. September 2026 weitet sich die Meldepflicht erneut aus, diesmal auf Belegdaten. Ein umfassendes künftiges E-Rechnungs-Rahmenwerk -- für inländische und innergemeinschaftliche B2B- sowie B2G-Transaktionen -- wurde im November 2025 zur öffentlichen Konsultation gestellt und am 31. März 2026 als Konzeptpapier aktualisiert, bleibt aber ein Vorschlag statt verabschiedetes Recht. Unabhängig vom eigenen innerstaatlichen Zeitplan Ungarns setzt die EU-Richtlinie VAT in the Digital Age (ViDA) ab dem 1. Juli 2030 eine bestätigte grenzüberschreitende B2B-Untergrenze.', '🇭🇺' FROM countries WHERE name_en = 'Hungary';

