INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '1. Juli 2025', 'Erste echte E-Rechnungspflicht beginnt (Energie/Wasser B2B)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Hungary' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '1. Sept. 2026', 'Belegdatenmeldung an die NAV wird verpflichtend' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Hungary' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '2030', 'Grenzüberschreitende EU-Untergrenze (ViDA, bestätigt)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Hungary' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Format & Standard', '[["RTIR-Datenformat", "Eigenes XML-Schema der NAV, übermittelt über die Online-Szamla-API -- das zugrunde liegende Rechnungsdokumentformat ist nicht vorgeschrieben"], ["E-Rechnungen Energie/Wasser (ab Juli 2025)", "Kein bestimmtes Format vorgeschrieben -- jedes von der NAV akzeptierte Format und jeder akzeptierte Übermittlungsweg ist zulässig"], ["B2G", "EN 16931, der europäische Standard für E-Rechnungen, wie in jedem EU-Mitgliedstaat"], ["Rechtsgrundlage", "Umsatzsteuergesetz (Gesetz CXXVII von 2007) und seine RTIR-Durchführungsverordnungen; die Energie-/Wasserpflicht ist in separater Sektorgesetzgebung geregelt"]]', 'Verwechseln Sie die verpflichtende XML-Datenübermittlung von RTIR nicht mit einer Pflicht, die Rechnung selbst in diesem Format auszustellen -- außerhalb des Energie-/Wassersektors kann ein ungarisches Unternehmen weiterhin eine Papier- oder PDF-Rechnung versenden und dabei vollständig RTIR-konform bleiben.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Kennungen & Registrierung', '[["Steuerpflichtigen-Registrierung", "Ungarische USt-/Steuernummer, bei der NAV registriert"], ["Technische RTIR-Anbindung", "Online-Szamla-Portal (onlineszamla.nav.gov.hu) -- direkte API-Integration oder manueller Web-Upload"], ["Zuständige Behörde", "Nemzeti Ado- es Vamhivatal (NAV) -- Nationale Steuer- und Zollverwaltung"], ["Ausländische umsatzsteuerlich registrierte Unternehmen", "Nach Registrierung zur Umsatzsteuer in Ungarn auf derselben Grundlage wie inländische Steuerpflichtige von RTIR erfasst"]]', 'Die meiste in Ungarn genutzte Rechnungs-/Buchhaltungssoftware verfügt bereits über eine integrierte RTIR-Meldung -- prüfen Sie, ob Ihre tatsächlich automatisch übermittelt, statt sich auf manuellen Upload zu verlassen, angesichts der knappen Frist für Softwarerechnungen.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Pflichtinhalt', '[["RTIR-Datenfelder", "Steuernummern von Aussteller/Käufer, Rechnungsnummer, Daten, aufgeschlüsselte USt-Angaben, Netto- und Bruttobeträge"], ["Softwarerechnungen", "Sofortige Meldung, ohne menschliches Eingreifen"], ["Manuelle/Papierrechnungen", "5 Kalendertage (USt 100.000-500.000 HUF) oder 1 Kalendertag (USt über 500.000 HUF) -- die ursprünglichen Schwellenwerte von 2018 prägen weiterhin die Fristen für manuelle Rechnungen, obwohl die Schwelle für den Meldeumfang selbst 2020 abgeschafft wurde"], ["Aufbewahrung", "8 Jahre für Rechnungen und RTIR-Übermittlungsantworten"]]', 'Die gestaffelten Fristen für manuelle Rechnungen sind ein Überbleibsel der ursprünglichen Schwellenwertgestaltung von 2018 -- wissenswert, auch wenn inzwischen jede Rechnung unabhängig vom Wert gemeldet werden muss.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Der Ablauf: erst ausstellen, dann melden', 'Außerhalb des Energie-/Wassersektors durchläuft eine ungarische Rechnung diese Abfolge -- beachten Sie, dass RTIR die DATEN der Rechnung meldet, nicht das Dokument selbst:', 'Die Rechnung ist bei Ausstellung unabhängig vom Format rechtsgültig -- die NAV wird nicht vorab um Freigabe oder Genehmigung gebeten, anders als bei den an anderer Stelle in diesem Tracker erfassten Freigabemodellen (Kolumbien, Argentinien, Jordanien). Nur bei B2B-Lieferungen von Energie/Wasser (seit Juli 2025) muss das Rechnungsdokument selbst tatsächlich elektronisch sein.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Hungary';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Rechnung an Käufer ausgestellt -- Papier, PDF oder elektronisch, alle rechtsgültig außerhalb von B2B Energie/Wasser' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Hungary' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Rechnungsdaten über Online Szamla an die NAV gemeldet -- sofort bei Softwarerechnungen' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Hungary' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'NAV gleicht gemeldete Rechnungsdaten mit eingereichten USt-Erklärungen ab' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Hungary' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Ab Sept. 2026: zugrunde liegende Belegdaten werden separat gemeldet, nach demselben Echtzeitprinzip' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Hungary' AND st.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Was heute tatsächlich verpflichtend ist, nach Ebenen', '[["RTIR-Datenmeldung", "Praktisch alle umsatzsteuerlich registrierten Unternehmen -- inländisches B2B, B2C, Export, innergemeinschaftlich (seit 2021)"], ["E-Rechnungsausstellung", "Nur Strom-, Erdgas- und Wasserversorger, B2B-Lieferungen an nicht-private Kunden (seit Juli 2025)"], ["Belegdatenmeldung", "Alle Unternehmen, ab 1. September 2026"], ["Allgemeine inländische B2B-E-Rechnung", "Nicht verpflichtend -- in einer Konsultation vom November 2025 vorgeschlagen, kein verabschiedetes Datum"]]', 'Es lohnt sich, genau zu klären, welche Ebene für Sie gilt: fast jedes ungarische Unternehmen meldet bereits nach RTIR, aber nur sehr wenige müssen bereits tatsächlich eine E-Rechnung ausstellen.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Das vorgeschlagene umfassende Rahmenwerk (noch kein Gesetz)', '[["Status", "Öffentliche Konsultation im Nov. 2025 eröffnet, aktualisiertes Konzeptpapier am 31. März 2026 veröffentlicht"], ["Vorgeschlagener Umfang", "Inländisches B2B, innergemeinschaftliches B2B und B2G"], ["Vorgeschlagenes Format", "Einheitliches XML nach EN 16931"], ["Vorgeschlagene Meldung durch den Käufer", "Inländische Käufer würden erhaltene Rechnungen innerhalb von 5 Tagen melden"]]', 'Behandeln Sie jedes Detail hier als Vorschlag, nicht als Zusage -- die eigene Konsultation der NAV macht deutlich, dass die endgültige Form und das Datum noch offen sind.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '💰 HUF 500.000 je RTIR-Meldeverstoß', NULL, NULL, 'Unternehmen drohen Bußgelder von bis zu 500.000 HUF je Rechnung, die nicht, verspätet, unvollständig, unrichtig oder wahrheitswidrig über RTIR gemeldet wird. Da der Anwendungsbereich von RTIR inzwischen nahezu universell ist, betrifft dieses Sanktionsrisiko fast jedes umsatzsteuerlich registrierte ungarische Unternehmen, nicht nur einen engen Ausnahmefall.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '📋 HUF 300.000 für das Ignorieren einer NAV-Klärungsanfrage', NULL, NULL, 'Seit dem 1. Januar 2025 zieht die Nichtbeantwortung einer NAV-Klärungsanfrage zu einer gemeldeten Rechnung innerhalb von 15 Tagen ein gesondertes Bußgeld von 300.000 HUF nach sich -- eine neuere, verfahrensrechtliche Sanktion zusätzlich zum oben genannten zentralen RTIR-Meldebußgeld.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🗓 Ein Regime, das schichtweise aufgebaut wurde, nicht mit einem einzigen Pflichtdatum', NULL, NULL, 'Ungarns Geschichte verlief in klar abgegrenzten Schritten, von denen jeder etwas anderes veränderte: die Einführung von RTIR (2018) und seine zwei Ausweitungen des Anwendungsbereichs (2020, 2021) bauten eine nahezu universelle Datenmeldepflicht auf; die Energie-/Wasserregel von 2025 fügte eine enge, aber echte E-Rechnungspflicht hinzu; 2026 weitet die Meldung auf Belege aus; und ein umfassendes B2B-/B2G-Rahmenwerk bleibt ein lebendiger Vorschlag statt eines festen Datums. Prüfen Sie, welche Ebene eine bestimmte Frist tatsächlich verändert, bevor Sie annehmen, dass sie für Ihr Unternehmen gilt.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Rechnung nicht, verspätet, unvollständig, unrichtig oder wahrheitswidrig über RTIR gemeldet', 'Bis zu HUF 500.000 je Rechnung', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Hungary' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Nichtbeantwortung einer NAV-Klärungsanfrage innerhalb von 15 Tagen (seit 1. Jan. 2025)', 'HUF 300.000', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Hungary' AND pr.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Prüfen Sie, ob Ihre RTIR-Meldung vollständig automatisiert ist und jeden Rechnungstyp abdeckt', 'RTIR erfasst inzwischen inländische B2B-, B2C-, Export- und innergemeinschaftliche Rechnungen ohne Wertschwelle -- prüfen Sie, ob Ihre Rechnungs-/Buchhaltungssoftware alle sofort meldet, nicht nur eine Teilmenge.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Hungary' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Wenn Sie Strom, Gas oder Wasser an ungarische Unternehmen liefern, wechseln Sie zu echter E-Rechnung', 'Seit dem 1. Juli 2025 erfordern B2B-Lieferungen in diesem Sektor eine tatsächliche elektronische Rechnung, nicht nur über RTIR gemeldete Daten -- prüfen Sie, ob Ihr Rechnungsprozess diesen Wechsel vollzogen hat.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Hungary' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bereiten Sie sich vor dem 1. September 2026 auf die Belegdatenmeldung vor', 'Prüfen Sie, ob Ihr Kassensystem bereits eine angeschlossene Registrierkasse oder E-Kasse nutzt -- falls nicht, planen Sie jetzt die manuelle 3-Tage-Belegmeldung und den vollständigen Übergang zu E-Kassen bis zum 1. Juli 2028 ein.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Hungary' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Verfolgen Sie die umfassende E-Rechnungs-Konsultation der NAV im Hinblick auf eine künftige inländische B2B-Pflicht', 'Die Konsultation vom November 2025 und das Konzeptpapier vom März 2026 schlagen eine einheitliche EN-16931-XML-Rechnungsstellung und eine Meldung durch den Käufer vor -- noch kein verabschiedetes Datum, aber angesichts der bereits weitreichenden RTIR-Meldeinfrastruktur beobachtenswert.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Hungary' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bereiten Sie sich ungeachtet dessen auf die bestätigte grenzüberschreitende EU-Untergrenze von 2030 vor', 'Jedes Unternehmen, das grenzüberschreitend innerhalb der EU Handel betreibt, benötigt ab dem 1. Juli 2030 EN-16931-konforme E-Rechnungs- und digitale Meldefähigkeit -- dieses Datum ist durch EU-Richtlinie festgelegt, nicht durch ungarisches Ermessen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Hungary' AND sp.sort_order = 4;

