INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'Nemzeti Ado- es Vamhivatal (NAV) — Nationale Steuer- und Zollverwaltung' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Hungary' AND pt.sort_order = 1;

-- ==================== fr ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Déclaration des données de transaction en temps réel (RTIR) depuis 2018, complétée par une obligation de facturation électronique B2B limitée au secteur de l''énergie/eau depuis 2025 -- pas encore d''obligation générale de facturation électronique B2B, bien qu''une soit en cours de consultation', 'Cette page d''analyse reflète les indications publiques de la NAV et les informations sectorielles disponibles début août 2026, et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Le futur cadre global de facturation électronique de la Hongrie en était encore au stade de la consultation publique au moment de la rédaction, sans date promulguée -- confirmez le statut actuel directement auprès de la NAV ou d''un conseiller fiscal hongrois avant de fonder vos décisions de conformité sur cette page.', 'Le système de déclaration des factures en temps réel (RTIR) de la Hongrie est l''un des régimes de déclaration des transactions les plus matures d''Europe : lancé le 1er juillet 2018 pour les factures B2B nationales dépassant un seuil de TVA de 100 000 HUF, le seuil a été supprimé le 1er juillet 2020, et le champ d''application a de nouveau été élargi le 1er janvier 2021 pour couvrir les factures B2C, d''exportation et intracommunautaires -- à ce stade, RTIR touchait pratiquement toute facture pertinente au regard de la TVA émise par une entreprise hongroise. Élément essentiel : RTIR déclare les DONNÉES de la facture au système Online Szamla de la NAV ; il n''a jamais exigé que la facture elle-même soit émise électroniquement. Cela a changé, de manière limitée, à compter du 1er juillet 2025 : les fournisseurs d''électricité, de gaz naturel et d''eau doivent désormais émettre de véritables factures électroniques pour les fournitures B2B à des clients non particuliers -- la première véritable obligation d''émission de facturation électronique en Hongrie, bien que sectorielle. À compter du 1er septembre 2026, le filet de déclaration s''élargit à nouveau, cette fois aux reçus. Par ailleurs, la NAV et le ministère de l''Économie nationale ont ouvert une consultation publique en novembre 2025, actualisée sous forme de document de concept le 31 mars 2026, sur un futur cadre global de facturation électronique couvrant les transactions B2B et B2G nationales et intracommunautaires -- proposé, mais pas encore promulgué. Quelle que soit la décision de la Hongrie au niveau national, le plancher transfrontalier ViDA de l''UE s''applique de toute façon à compter du 1er juillet 2030.', 'RTIR transmet les données des factures via l''API Online Szamla de la NAV, généralement selon le schéma XML propre à la NAV généré directement par les logiciels de facturation/comptabilité ; il n''impose pas de format de document de facture spécifique, la facture elle-même pouvant rester au format papier ou PDF en dehors du secteur de l''énergie/eau. Là où une véritable obligation de facturation électronique s''applique (fournitures B2B d''électricité, de gaz et d''eau depuis juillet 2025), la législation ne prescrit pas non plus de format spécifique -- tout format et toute méthode de transmission acceptés par la NAV sont valables. La facturation B2G suit la norme européenne EN 16931, comme dans tout État membre de l''UE.', 'L''obligation de déclaration de données de RTIR couvre désormais pratiquement toutes les entreprises assujetties à la TVA en Hongrie, aussi bien pour les factures B2B nationales que B2C, d''exportation et intracommunautaires -- un champ d''application qui a nécessité trois étapes (2018, 2020, 2021) pour être atteint. En complément, l''obligation d''émission de facturation électronique de juillet 2025 est délibérément étroite : uniquement les fournisseurs d''électricité, de gaz naturel et d''eau, uniquement pour les fournitures B2B à des clients non particuliers. À partir de septembre 2026, toutes les entreprises -- pas seulement celles assujetties à la TVA effectuant des fournitures B2B -- entrent dans le champ de la déclaration des données de reçus. Aucune obligation générale nationale de facturation électronique B2B n''existe encore ; le champ d''application proposé par la consultation de novembre 2025 (B2B national, B2B intra-UE et B2G) n''a pas de date confirmée.', 'L''obligation de déclaration de RTIR étant déjà proche de l''universalité, le travail à court terme de la plupart des entreprises hongroises consiste davantage à superposer de nouvelles obligations à la connectivité RTIR existante qu''à construire la conformité à partir de zéro : les fournisseurs d''énergie/eau ont besoin d''une véritable capacité de facturation électronique, la plupart des autres entreprises doivent se préparer à la déclaration des données de reçus d''ici septembre 2026, et toutes doivent suivre la consultation globale sur la facturation électronique en vue d''une future obligation B2B nationale.', 'La Hongrie appuie RTIR sur des sanctions réelles et documentées : jusqu''à 500 000 HUF par facture non déclarée, déclarée en retard, de façon incomplète, incorrecte ou mensongère, plus une amende distincte de 300 000 HUF (depuis le 1er janvier 2025) en cas de non-réponse à une demande de clarification de la NAV dans un délai de 15 jours. Aucun barème de sanctions spécifique à l''obligation plus étroite de facturation électronique énergie/eau de juillet 2025 n''a été trouvé lors des recherches au moment de la rédaction.', 'L''Administration nationale hongroise des impôts et des douanes (NAV) exploite la déclaration des factures en temps réel (RTIR) depuis le 1er juillet 2018, couvrant désormais pratiquement toute facture pertinente au regard de la TVA émise par une entreprise hongroise -- mais RTIR est une obligation de déclaration de DONNÉES de transaction, non une obligation de format de facturation électronique ; la facture sous-jacente peut rester au format papier ou PDF. Cela a changé de manière limitée à compter du 1er juillet 2025, lorsque les fournisseurs d''électricité, de gaz naturel et d''eau ont été tenus d''émettre effectivement des factures électroniques pour les fournitures B2B à des clients non particuliers -- la première véritable obligation d''émission de facturation électronique en Hongrie, bien que sectorielle plutôt qu''à l''échelle de l''économie. À compter du 1er septembre 2026, la déclaration obligatoire s''étend à nouveau, cette fois aux données de reçus. Un futur cadre global de facturation électronique -- couvrant les transactions B2B et B2G nationales et intra-UE -- a été soumis à consultation publique en novembre 2025 et actualisé sous forme de document de concept le 31 mars 2026, mais reste une proposition et non une règle promulguée. Indépendamment du calendrier national propre à la Hongrie, la directive européenne TVA à l''ère numérique (ViDA) fixe un plancher transfrontalier B2B confirmé à compter du 1er juillet 2030.', '🇭🇺' FROM countries WHERE name_en = 'Hungary';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er juil. 2018', 'Lancement de la déclaration des données de factures en temps réel (RTIR)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Hungary' AND s.sort_order = 0;
