INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er juil. 2025', 'Entrée en vigueur de la première véritable obligation de facturation électronique (énergie/eau B2B)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Hungary' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er sept. 2026', 'La déclaration des données de reçus à la NAV devient obligatoire' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Hungary' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '2030', 'Plancher transfrontalier de l''UE (ViDA, confirmé)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Hungary' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Format et norme', '[["Format de données RTIR", "Schéma XML propre à la NAV, soumis via l''API Online Szamla -- le format du document de facture sous-jacent n''est pas imposé"], ["Factures électroniques énergie/eau (depuis juil. 2025)", "Aucun format spécifique prescrit -- tout format et toute méthode de transmission acceptés par la NAV conviennent"], ["B2G", "EN 16931, la norme européenne de facturation électronique, comme dans tout État membre de l''UE"], ["Base légale", "Loi sur la TVA (loi CXXVII de 2007) et ses décrets d''application de RTIR ; l''obligation énergie/eau relève d''une législation sectorielle distincte"]]', 'Ne confondez pas la soumission obligatoire de données XML de RTIR avec une obligation d''émettre la facture elle-même dans ce format -- en dehors du secteur énergie/eau, une entreprise hongroise peut toujours envoyer une facture papier ou PDF tout en restant pleinement conforme à RTIR.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Identifiants et enregistrement', '[["Enregistrement du contribuable", "Numéro de TVA/fiscal hongrois, enregistré auprès de la NAV"], ["Connexion technique RTIR", "Portail Online Szamla (onlineszamla.nav.gov.hu) -- intégration API directe ou téléversement manuel via le web"], ["Organisme responsable", "Nemzeti Ado- es Vamhivatal (NAV) -- Administration nationale des impôts et des douanes"], ["Entreprises étrangères assujetties à la TVA", "Concernées par RTIR dans les mêmes conditions que les contribuables nationaux une fois enregistrées à la TVA en Hongrie"]]', 'La plupart des logiciels de facturation/comptabilité utilisés en Hongrie intègrent déjà la déclaration RTIR -- vérifiez que le vôtre soumet effectivement de façon automatique plutôt que de dépendre d''un téléversement manuel, compte tenu du délai très court pour les factures logicielles.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Contenu obligatoire', '[["Champs de données RTIR", "Numéros fiscaux de l''émetteur/acheteur, numéro de facture, dates, ventilation détaillée de la TVA, montants nets et bruts"], ["Factures logicielles", "Déclarées immédiatement, sans intervention humaine"], ["Factures manuelles/papier", "5 jours calendaires (TVA de 100 000 à 500 000 HUF) ou 1 jour calendaire (TVA supérieure à 500 000 HUF) -- les seuils initiaux de 2018 continuent de déterminer les délais pour les factures manuelles, même si le seuil du champ d''application de la déclaration lui-même a été supprimé en 2020"], ["Conservation", "8 ans pour les factures et les réponses de soumission RTIR"]]', 'Les paliers de délai pour les factures manuelles sont un héritage de la conception initiale du seuil de 2018 -- utile à connaître même si toute facture, quelle que soit sa valeur, doit désormais être déclarée.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Le flux : émission puis déclaration', 'En dehors du secteur énergie/eau, une facture hongroise suit cette séquence -- notez que RTIR déclare les DONNÉES de la facture, pas le document lui-même :', 'La facture est juridiquement valable dès son émission, quel que soit son format -- la NAV n''est pas sollicitée pour la valider ou l''approuver au préalable, contrairement aux obligations de type dédouanement couvertes ailleurs dans ce suivi (Colombie, Argentine, Jordanie). Ce n''est que pour les fournitures B2B d''énergie/eau (depuis juillet 2025) que le document de facture lui-même doit réellement être électronique.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Hungary';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Facture émise à l''acheteur -- papier, PDF ou électronique, toutes juridiquement valables en dehors du B2B énergie/eau' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Hungary' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Données de la facture déclarées à la NAV via Online Szamla -- immédiatement pour les factures logicielles' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Hungary' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'La NAV recoupe les données de facture déclarées avec les déclarations de TVA déposées' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Hungary' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Dès sept. 2026 : les données de reçu sous-jacentes sont déclarées séparément, selon le même principe de temps réel' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Hungary' AND st.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Ce qui est réellement obligatoire aujourd''hui, par niveau', '[["Déclaration de données RTIR", "Pratiquement toutes les entreprises assujetties à la TVA -- B2B national, B2C, exportation, intracommunautaire (depuis 2021)"], ["Émission de factures électroniques", "Uniquement les fournisseurs d''électricité, de gaz naturel et d''eau, fournitures B2B à des clients non particuliers (depuis juil. 2025)"], ["Déclaration des données de reçus", "Toutes les entreprises, à compter du 1er septembre 2026"], ["Facturation électronique B2B nationale générale", "Non obligatoire -- proposée dans une consultation de novembre 2025, sans date promulguée"]]', 'Il convient de bien préciser quel niveau vous concerne : presque toute entreprise hongroise déclare déjà via RTIR, mais très peu sont encore tenues d''émettre réellement une facture électronique.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Le cadre global proposé (pas encore une loi)', '[["Statut", "Consultation publique ouverte en nov. 2025, document de concept actualisé publié le 31 mars 2026"], ["Champ d''application proposé", "B2B national, B2B intra-UE et B2G"], ["Format proposé", "XML unifié conforme à l''EN 16931"], ["Déclaration côté acheteur proposée", "Les acheteurs nationaux déclareraient les factures reçues dans un délai de 5 jours"]]', 'Considérez chaque détail ici comme une proposition, non un engagement -- la consultation de la NAV elle-même indique clairement que la forme finale et la date restent ouvertes.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '💰 HUF 500 000 par manquement à la déclaration RTIR', NULL, NULL, 'Les entreprises s''exposent à des amendes pouvant atteindre 500 000 HUF par facture non déclarée, déclarée en retard, de façon incomplète, incorrecte ou mensongère via RTIR. Le champ d''application de RTIR étant désormais quasi universel, cette exposition aux sanctions concerne presque toute entreprise hongroise assujettie à la TVA, et non un cas marginal restreint.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '📋 HUF 300 000 pour avoir ignoré une demande de clarification de la NAV', NULL, NULL, 'Depuis le 1er janvier 2025, le fait de ne pas répondre à une demande de clarification de la NAV concernant une facture déclarée dans un délai de 15 jours entraîne une amende distincte de 300 000 HUF -- une sanction procédurale plus récente qui s''ajoute à l''amende principale de déclaration RTIR mentionnée ci-dessus.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🗓 Un régime construit par couches, pas par une seule date d''obligation', NULL, NULL, 'L''histoire de la Hongrie a progressé par étapes distinctes, chacune modifiant un élément différent : le lancement de RTIR (2018) et ses deux élargissements de champ d''application (2020, 2021) ont bâti une obligation de déclaration de données quasi universelle ; la règle énergie/eau de 2025 a ajouté une obligation d''émission de facturation électronique étroite mais réelle ; 2026 étend la déclaration aux reçus ; et un cadre global B2B/B2G reste une proposition vivante plutôt qu''une date fixe. Vérifiez quel niveau une échéance donnée modifie réellement avant de supposer qu''elle s''applique à votre entreprise.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Hungary' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Facture non déclarée, déclarée en retard, de façon incomplète, incorrecte ou mensongère via RTIR', 'Jusqu''à HUF 500 000 par facture', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Hungary' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Non-réponse à une demande de clarification de la NAV dans un délai de 15 jours (depuis le 1er janv. 2025)', 'HUF 300 000', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Hungary' AND pr.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez que votre déclaration RTIR est entièrement automatisée et couvre tous les types de factures', 'RTIR couvre désormais les factures B2B nationales, B2C, d''exportation et intracommunautaires sans seuil de valeur -- vérifiez que votre logiciel de facturation/comptabilité les déclare toutes immédiatement, pas seulement un sous-ensemble.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Hungary' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Si vous fournissez de l''électricité, du gaz ou de l''eau à des entreprises hongroises, passez à une véritable facturation électronique', 'Depuis le 1er juillet 2025, les fournitures B2B dans ce secteur exigent une véritable facture électronique, pas seulement des données déclarées via RTIR -- vérifiez que votre processus de facturation a effectué ce changement.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Hungary' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Préparez-vous à la déclaration des données de reçus avant le 1er septembre 2026', 'Vérifiez si votre point de vente utilise déjà une caisse enregistreuse connectée ou électronique -- sinon, prévoyez dès maintenant la déclaration manuelle des reçus sous 3 jours et la transition complète vers les caisses électroniques d''ici le 1er juillet 2028.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Hungary' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Suivez la consultation globale de la NAV sur la facturation électronique en vue d''une future obligation B2B nationale', 'La consultation de novembre 2025 et le document de concept de mars 2026 proposent une facturation XML unifiée conforme à l''EN 16931 et une déclaration côté acheteur -- pas encore de date promulguée, mais à surveiller compte tenu de la portée déjà large de l''infrastructure de déclaration de RTIR.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Hungary' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Préparez-vous de toute façon au plancher transfrontalier confirmé de l''UE de 2030', 'Toute entreprise commerçant à l''échelle transfrontalière au sein de l''UE a besoin d''une capacité de facturation électronique et de déclaration numérique conforme à l''EN 16931 à compter du 1er juillet 2030 -- cette date est fixée par la directive européenne, non par la discrétion hongroise.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Hungary' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'NAV — Online Szamla (déclaration des factures en temps réel)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Hungary' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Nemzeti Ado- es Vamhivatal (NAV) — Administration nationale des impôts et des douanes' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Hungary' AND pt.sort_order = 1;
